import{_ as n,o as i,c as a,a5 as h}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"FR 3.6.9 — Phê duyệt công việc","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-9-approval-sequence-creator-manager-client/spec.md","filePath":"feature/content-task-workflow/3-6-9-approval-sequence-creator-manager-client/spec.md"}'),e={name:"feature/content-task-workflow/3-6-9-approval-sequence-creator-manager-client/spec.md"};function o(c,t,r,l,s,g){return i(),a("div",null,[...t[0]||(t[0]=[h('<h1 id="fr-3-6-9-—-phe-duyet-cong-viec" tabindex="-1">FR 3.6.9 — Phê duyệt công việc <a class="header-anchor" href="#fr-3-6-9-—-phe-duyet-cong-viec" aria-label="Permalink to &quot;FR 3.6.9 — Phê duyệt công việc&quot;">​</a></h1><h2 id="ui-moi-nhat-—-trang-duyet-bai-rieng-trong-workspace" tabindex="-1">UI mới nhất — trang Duyệt bài riêng trong Workspace <a class="header-anchor" href="#ui-moi-nhat-—-trang-duyet-bai-rieng-trong-workspace" aria-label="Permalink to &quot;UI mới nhất — trang Duyệt bài riêng trong Workspace&quot;">​</a></h2><p>Người dùng chốt mục riêng trên menu Workspace, không đặt phần nội dung/decision/history trong Task Detail. Route <code>/workspaces/:id/task-approvals?task=&lt;id&gt;</code>; mặc định danh sách POST IN_REVIEW, có tìm kiếm/phân trang/lọc trạng thái để xem bài đang làm/đã kết thúc. Chọn bài mở vùng xem/duyệt cùng trang, không modal chi tiết; mobile có quay về danh sách. Manager/Creator/Client được xem theo ACL hiện có, action vẫn do API quyết định. Task Detail giữ brief/start/comments và liên kết sang trang duyệt/Editor cho POST. Không thêm DB hay thay BA/publisher/Yjs; không giả danh sách là “của tôi” khi API chưa lọc theo người duyệt. Key vi/en song song, semantic light/dark, keyboard/loading/error/empty và giữ note khi đổi bài.</p><h2 id="quyet-đinh-moi-nhat-—-18-10-2026" tabindex="-1">Quyết định mới nhất — 18/10/2026 <a class="header-anchor" href="#quyet-đinh-moi-nhat-—-18-10-2026" aria-label="Permalink to &quot;Quyết định mới nhất — 18/10/2026&quot;">​</a></h2><p>Người dùng yêu cầu bỏ hoàn toàn cờ rollout POST integration. Soạn/lưu và gửi/thu hồi/duyệt/từ chối hoạt động theo schema, ACL, trạng thái và revision/version, không phụ thuộc biến môi trường. Worker handoff Admin hoạt động bình thường, chỉ xử lý event riêng. Không thay publish; nguy cơ publish lưu toàn document vẫn bàn giao thành viên phụ trách. Các mô tả gate tắt bên dưới là lịch sử, không còn là hướng dẫn hiện hành.</p><table tabindex="0"><thead><tr><th>Thuộc tính</th><th>Giá trị</th></tr></thead><tbody><tr><td>FR / Use case / Task</td><td>3.6.9 / UC-47 / DA-E51-03; chưa xác minh mã Jira số</td></tr><tr><td>Vai trò</td><td>Creator được giao, Manager thực tế của Workspace, Client đang hoạt động</td></tr><tr><td>Phiên bản</td><td>3.0 — BA được người dùng xác nhận ngày 2026-10-18</td></tr><tr><td>Tiến độ</td><td>Giai đoạn 1–3, core Task–Post/Editor giai đoạn 4 và UI duyệt giai đoạn 5 đã có code/kiểm thử cô lập; mutation mặc định tắt. Còn checkpoint publisher, SQL/inbox/Gateway end-to-end và rollout giai đoạn 6; Atlas APPLY chưa thực hiện</td></tr><tr><td>Phụ trách</td><td>Lộc tiếp nhận FR 3.6.9 theo yêu cầu người dùng; chưa tuyên bố Jira đã đổi assignee</td></tr></tbody></table><p>Thay thế quy tắc QC, trạng thái trung gian và skip approval cũ của FR 3.6.9. Quyết định 2026-10-18: dùng <code>/editor</code> trước; một bản nội dung hiện tại, không snapshot; thu hồi trước quyết định Manager; một Client bất kỳ quyết định; thiếu Client thì chặn gửi duyệt. <a href="./plan.html">Kế hoạch</a>, <a href="./task.html">checklist</a>, <a href="./test.html">kiểm thử</a>.</p><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Cho Creator gửi kết quả tới Manager và Client khi cần, theo dõi quyết định từng lượt mà không trộn với bình luận Task hoặc thao tác xuất bản.</p><h2 id="_2-user-story-va-pham-vi" tabindex="-1">2. User story và phạm vi <a class="header-anchor" href="#_2-user-story-va-pham-vi" aria-label="Permalink to &quot;2. User story và phạm vi&quot;">​</a></h2><ul><li>Creator được giao gửi bài POST từ <code>/editor</code>, thu hồi đúng thời điểm và sửa lại sau từ chối.</li><li>Manager xem bài được liên kết, duyệt hoặc từ chối có lý do.</li><li>Client quyết định ở bước của khách hàng và xem lịch sử duyệt.</li><li>Khung workflow dùng chung cho năm loại Task; đợt này chỉ nối nội dung POST. Chưa có adapter nội dung thì không gửi/duyệt giả các loại khác.</li></ul><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance criteria&quot;">​</a></h2><h3 id="quyen-noi-dung-va-luot-duyet" tabindex="-1">Quyền, nội dung và lượt duyệt <a class="header-anchor" href="#quyen-noi-dung-va-luot-duyet" aria-label="Permalink to &quot;Quyền, nội dung và lượt duyệt&quot;">​</a></h3><ul><li><strong>AC-01 — Scope:</strong> xác minh User/membership đang hoạt động, đúng Workspace/Task. Owner Agency không tự có quyền Manager. Chỉ assignee Creator được submit/withdraw; Manager/Client đúng bước mới approve/reject. Client vẫn xem/bình luận mọi Task trong Workspace theo FR 3.6.3.</li><li><strong>AC-02 — Một bài:</strong> Task POST liên kết tối đa một Post cùng Workspace; Post độc lập không bắt buộc có Task. Chưa có bài thì chưa submit. Mở lại phải mở đúng bài đã lưu, không tạo bản mới do bài bị khóa/lỗi API. Mô tả yêu cầu Task không phải kết quả nội dung đã viết.</li><li><strong>AC-03 — Một bản hiện tại:</strong> không thêm snapshot, kho phiên bản Approval, <code>reviewSnapshotId</code> hay <code>reviewContentVersion</code>. Khi Task <code>IN_REVIEW</code>, khóa sửa caption/hashtag/media/kênh của bài liên kết ở backend và UI; không chỉ dựa vào <code>posts.status</code>. Giữ <code>content_version</code> hiện có phục vụ Admin moderation/concurrency, không xây kho phiên bản mới.</li><li><strong>AC-04 — Giới hạn lịch sử:</strong> sau reject/withdraw hợp lệ, sửa chính bài hiện tại. Lịch sử chỉ giữ người quyết định, bước, lượt, nhận xét và thời gian; không xem/diff nội dung cũ vì không lưu bản cũ. Không gắn nhãn như thể nội dung hiện tại là nội dung của lượt cũ. Không xóa content history của module khác.</li><li><strong>AC-05 — Submit:</strong> chỉ từ <code>IN_PROGRESS</code>, assignee còn hợp lệ, có bài POST hợp lệ theo validation Editor hiện có (ít nhất caption không trắng). Mở trang không tự start/submit. Không bổ sung quy tắc chặn nộp quá hạn trong FR này. Gửi thành công chuyển <code>IN_REVIEW/MANAGER</code>.</li><li><strong>AC-06 — Lượt:</strong> lượt đầu là 1; mỗi lần gửi lại thành công sau reject/withdraw dùng lượt tiếp theo. Chỉ approve/reject tạo decision trong <code>task_approvals</code>, không tạo sẵn dòng cho người chưa duyệt. Một lượt tối đa hai decision: Manager, Client. Không tạo collection round riêng; không kế thừa hiệu lực approval cũ.</li></ul><h3 id="chuyen-buoc-va-ngoai-le" tabindex="-1">Chuyển bước và ngoại lệ <a class="header-anchor" href="#chuyen-buoc-va-ngoai-le" aria-label="Permalink to &quot;Chuyển bước và ngoại lệ&quot;">​</a></h3><ul><li><strong>AC-07 — Manager:</strong> approve ở bước MANAGER: không yêu cầu Client thì FINISHED; có yêu cầu thì giữ IN_REVIEW, chuyển bước CLIENT.</li><li><strong>AC-08 — Client:</strong> một Client bất kỳ còn hoạt động trong Workspace quyết định tại bước CLIENT; không yêu cầu tất cả hoặc chỉ định đại diện. Chỉ decision hợp lệ đầu tiên được ghi nhận. Client approve chuyển FINISHED.</li><li><strong>AC-09 — Thiếu người duyệt:</strong> yêu cầu Client nhưng chưa có Client có tài khoản hoạt động thì chặn submit, giữ nguyên Task/Post/lượt, báo Manager bổ sung Client. ClientProfile chưa gắn User đăng nhập không đủ điều kiện. Hết Client khi đang chờ Client: giữ nguyên bước, không tự approve/skip; dùng chức năng quản lý thành viên hiện có để bổ sung. Không xây flow mời mới trong FR này.</li><li><strong>AC-10 — Reject:</strong> Manager/Client đúng bước nhập lý do không trắng; append REJECT, Task về IN_PROGRESS, xóa bước chờ. Creator sửa bài hiện tại, gửi lại từ Manager ở lượt mới. Không sửa/xóa decision cũ.</li><li><strong>AC-11 — Withdraw:</strong> assignee Creator chỉ thu hồi khi IN_REVIEW/MANAGER và Manager chưa quyết định lượt hiện tại. Task về IN_PROGRESS, xóa bước chờ, mở sửa bài hiện tại. Không tạo REJECT thay người duyệt. Sau Manager approve đang chờ Client thì không thu hồi. Withdraw và Manager decision đồng thời: chỉ một thao tác hợp lệ thắng.</li><li><strong>AC-12 — Giữ nền Task:</strong> không QC/review chéo; giữ TODO/IN_PROGRESS/IN_REVIEW/FINISHED/CANCELLED. Sau lần bắt đầu đầu tiên Manager không sửa brief/deadline/giao lại, kể cả sau reject/withdraw. Không mở lại FINISHED hoặc chọn trạng thái tùy ý. Giữ field <code>task_approvals.comment</code>; UI gọi “Nhận xét duyệt”, khác bình luận Task.</li><li><strong>AC-13 — Cancel/Campaign:</strong> Task bị hủy hoặc Campaign đã hoàn thành không nhận submit/decision/withdraw. Hủy Task đang duyệt theo flow hiện có phải chặn decision tiếp theo, giữ lịch sử, không mở lại. Giữ điều kiện hoàn thành Campaign: còn Task chưa kết thúc vẫn chặn.</li><li><strong>AC-14 — Nội dung/publishing:</strong> bước cuối chỉ hoàn thành Task, không enqueue/publish bài thật. Bài đã chốt không được sửa bằng flow draft để làm khác kết quả được duyệt. Admin moderation độc lập, không thay quyết định Manager/Client. Không thay Yjs, AI hoặc publisher; phối hợp các điểm tích hợp có ảnh hưởng module khác trước rollout.</li><li><strong>AC-15 — Concurrency:</strong> mutation nhận revision/lượt đang xem; request cũ trả conflict, không cập nhật nửa chừng hoặc tạo decision/thông báo trùng. Post đã đổi so với bản đang xem thì không tự duyệt/gửi thay người dùng. Chỉ báo thành công sau commit.</li><li><strong>AC-16 — Notification:</strong> in-app cho người duyệt bước tiếp theo khi submit/chuyển bước; reject báo assignee Creator. Không email. Recheck quyền/lượt/bước; bỏ trùng và thông báo chờ duyệt lỗi thời. Giữ hành vi notification bình luận/giao việc hiện có.</li></ul><h2 id="_4-state-machine" tabindex="-1">4. State machine <a class="header-anchor" href="#_4-state-machine" aria-label="Permalink to &quot;4. State machine&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trước</th><th>Actor / hành động</th><th>Sau</th></tr></thead><tbody><tr><td>TODO</td><td>Assignee Creator / Bắt đầu (FR 3.6.2 hiện có)</td><td>IN_PROGRESS</td></tr><tr><td>IN_PROGRESS</td><td>Assignee Creator / Gửi duyệt</td><td>IN_REVIEW / MANAGER</td></tr><tr><td>IN_REVIEW / MANAGER</td><td>Manager / Duyệt, không cần Client</td><td>FINISHED, reviewStep=null</td></tr><tr><td>IN_REVIEW / MANAGER</td><td>Manager / Duyệt, cần Client</td><td>IN_REVIEW / CLIENT</td></tr><tr><td>IN_REVIEW / CLIENT</td><td>Một Client active / Duyệt</td><td>FINISHED, reviewStep=null</td></tr><tr><td>IN_REVIEW / MANAGER hoặc CLIENT</td><td>Đúng người duyệt / Từ chối có lý do</td><td>IN_PROGRESS, reviewStep=null</td></tr><tr><td>IN_REVIEW / MANAGER, chưa decision</td><td>Assignee Creator / Thu hồi</td><td>IN_PROGRESS, reviewStep=null</td></tr><tr><td>Task chưa kết thúc</td><td>Flow hủy được cấp quyền hiện có</td><td>CANCELLED; không còn quyền duyệt</td></tr></tbody></table><p>Ngoài IN_REVIEW, writer mới để reviewStep=null. Legacy QC/thiếu bước/lượt chưa xác minh: chỉ đọc và báo cần rà soát, không tự reinterpret/backfill.</p><h2 id="_5-ui-ux-va-ui-states" tabindex="-1">5. UI/UX và UI states <a class="header-anchor" href="#_5-ui-ux-va-ui-states" aria-label="Permalink to &quot;5. UI/UX và UI states&quot;">​</a></h2><p>Giữ popup Task Detail hiện có; thêm phần “Phê duyệt” gồm bước chờ, lượt, bài hiện tại và lịch sử decision. Không thay layout danh sách, Chat hoặc editor khác. Người có quyền đọc Task xem được lịch sử; quyền action lấy từ backend, không suy từ lockReason sửa brief.</p><ul><li>Creator lưu bài thành công rồi submit; chờ Manager có Withdraw, chờ Client chỉ xem.</li><li>Manager/Client xem bài, Approve hoặc Reject; lý do trong Dialog ứng dụng, không window.confirm/prompt/alert.</li><li>Missing Post/thiếu Client/loại chưa hỗ trợ: hiển thị nguyên nhân và cách xử lý, không báo thành công giả.</li><li>Loading/submitting: giữ bố cục, disable thao tác trùng, aria-busy/status phù hợp. Lỗi gần field; conflict giữ lý do đang nhập và tải lại trạng thái, không tự replay mutation cũ.</li><li>Label/focus/keyboard rõ; focus vào lỗi khi gửi thất bại, trả focus khi đóng Dialog; không chỉ dùng màu. Refresh Approval không làm mất bình luận đang viết.</li><li><strong>AC-17 — i18n/theme:</strong> key song song trong <code>src/i18n/locales/{vi,en}/tasks.json</code> và <code>editor.json</code> khi đổi text Editor. Dùng token semantic, light/dark, 375/768/1440px; không tạo theme/layout mới.</li></ul><p>Keys dự kiến <code>tasks.review</code>: title, currentRound, currentStep, steps.manager, steps.client, submit, withdraw, approve, reject, reviewNote, reasonRequired, history, historyNoContentVersions, noHistory, contentUnavailable, missingClient, waitingForClient, pending, success, conflict, unsupportedType, legacyReviewRequired, errors.<em>. Text Editor dùng editor.review.</em>; không đưa bài/lý do nhạy cảm vào notification chung.</p><h2 id="_6-api-contract-đe-xuat" tabindex="-1">6. API contract đề xuất <a class="header-anchor" href="#_6-api-contract-đe-xuat" aria-label="Permalink to &quot;6. API contract đề xuất&quot;">​</a></h2><p>Prefix <code>/api/v1/workspaces/{workspaceId}/tasks/{taskId}</code>:</p><table tabindex="0"><thead><tr><th>Method / suffix</th><th>Mục đích</th></tr></thead><tbody><tr><td>GET /review</td><td>Trạng thái, lượt, bước, bài liên kết, allowedActions và lý do chặn</td></tr><tr><td>POST /submit</td><td>Gửi bài hiện tại ở lượt đầu/lượt mới</td></tr><tr><td>POST /withdraw</td><td>Thu hồi trước decision Manager</td></tr><tr><td>POST /approve</td><td>Ghi decision duyệt đúng bước</td></tr><tr><td>POST /reject</td><td>Ghi decision từ chối có lý do</td></tr><tr><td>GET /approvals</td><td>Lịch sử append-only theo lượt</td></tr></tbody></table><p>Giữ ApiResponse; shape/CAS và contract tìm/tạo bài theo Task ở <a href="./plan.html#3-api-contract-đích">plan §3</a>. Sáu endpoint review/approvals/submit/withdraw/approve/reject đã có code backend giai đoạn 3; chưa được mở mutation trên môi trường dùng chung. Endpoint tìm/tạo bài theo Task thuộc giai đoạn 4.</p><h2 id="_7-error-handling-va-edge-cases" tabindex="-1">7. Error handling và edge cases <a class="header-anchor" href="#_7-error-handling-va-edge-cases" aria-label="Permalink to &quot;7. Error handling và edge cases&quot;">​</a></h2><ul><li>401 mất/hết phiên; 403 sai role/bước/membership; 404 Task/Post ngoài scope.</li><li>400 validation reason/caption/input; 409 sai trạng thái/revision/lượt, thiếu bài/người duyệt; 503 schema/storage/transaction chưa sẵn sàng. Mã ở plan; không coi lỗi migration là lỗi nhập liệu.</li><li>Hai Client quyết định ngược nhau; withdraw cùng approve; Post save cùng submit; cancel cùng approve: chỉ một kết quả hợp lệ, không approval mồ côi.</li><li>Hết Client giữa lượt không làm mất Manager approval. Manager thay thế: chỉ Manager active hiện tại được quyết định, không gắn cứng người cũ.</li><li>Admin đổi Post status không tự là decision Task; khóa nội dung theo Task vẫn có hiệu lực. Không tự đặt quy tắc Admin BLOCK đổi Task status.</li><li>Chốt bổ sung 18/10: nếu Admin đưa bài về DRAFT trong lúc Task vẫn IN_REVIEW, giữ nguyên lượt/bước. Creator vẫn thu hồi trước quyết định Manager; Manager/Client đúng bước vẫn từ chối có lý do để sửa. Không cho APPROVE khi Post không còn PENDING_APPROVAL; không tự chuyển Admin BLOCK thành Task REJECT.</li><li>Bài gắn Task lưu qua API Task với revision/version bắt buộc. PATCH/submit Post cũ từ chối bài linked và hướng sang API Task; bài độc lập giữ contract cũ. Không fallback tạo bài độc lập để vượt lỗi/khóa.</li><li>External media URL có thể đổi nội dung ngoài hệ thống: chỉ khóa field/quan hệ trong hệ thống; không tuyên bố lưu bất biến byte của tài nguyên bên thứ ba.</li></ul><h2 id="_8-definition-of-done-va-out-of-scope" tabindex="-1">8. Definition of Done và out of scope <a class="header-anchor" href="#_8-definition-of-done-va-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done và out of scope&quot;">​</a></h2><p>FR chỉ hoàn thành khi API + UI + liên kết POST + khóa sửa + notification + hồi quy được kiểm chứng theo test.md. Giai đoạn 1 chỉ hoàn thành tài liệu; không đánh Done Jira/FR, không APPLY Atlas/init/seed/clean dữ liệu.</p><p>Checkpoint giai đoạn 2 (2026-10-18): <a href="./../../../database/task-approval-setup.html">migration/setup</a> đã có, init/checker đồng bộ và test DB cô lập đã chạy. Atlas chỉ kiểm kê đọc, còn hai active review chưa xác minh nên chưa APPLY. Không coi đây là Approval runtime đã hoàn thành.</p><p>Rollout giai đoạn 3: API read/history được triển khai độc lập, mutation mặc định khóa bằng cờ kỹ thuật <code>app.task-approval.post-integration-ready=false</code>. Chưa nối guard mọi Post writer/hook Admin ở giai đoạn 4 thì không bật cờ trên môi trường dùng chung. Read vẫn trả trạng thái/lịch sử; allowedActions=false với lý do tích hợp chưa sẵn sàng. Đây là khóa rollout an toàn, không phải trạng thái Task hoặc BA mới.</p><p>Ngoài phạm vi: snapshot/diff các lượt; role/QC mới; editor/Yjs mới; mở lại FINISHED; nội dung chuyên biệt bốn loại Task còn lại; tự publish/đổi queue/callback; email; thay Admin moderation; backfill legacy chưa duyệt allowlist. Report 3/4 chính thức và thông báo team/Jira là checkpoint bàn giao, không tuyên bố đã làm.</p><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../ba/05-content-task-workflow.html">BA Task</a>, <a href="./../../../ba/use-cases/04-content-task-workflow.html">UC-47</a>, <a href="./../../../ba/12-state-machines.html">state machines</a>, <a href="./../../../ba/11-data-entities-glossary.html">glossary</a>, <a href="./../task-structure-simplification/spec.html">Task structure</a>, <a href="./../task-workflow-contract.html">contract Task</a>, <a href="./../task-approval-simplification/spec.html">đề xuất lịch sử</a>, <a href="./../../../team_guide.html">team guide</a>.</p>',36)])])}const p=n(e,[["render",o]]);export{u as __pageData,p as default};
